// Des: Scan PDF objects, read dicts, inflate streams, capped
// Flo: check header + encrypt flag > scan "N G obj" bodies (last wins) > expand object streams > dict pairs > stream decode with size, ratio and total caps
// I/O: PDF bytes (caller) > Doc (object table), dict Pairs, decoded stream bytes; typed errors BadPdf Encrypted TooMany Bomb Unsupported BadStream
// ===================================================================
const std = @import("std"); const mem = std.mem; const flate = std.compress.flate;
const CF = .{ .objz = 60000, .infz = 16 << 20, .totz = 128 << 20, .rati = 1000, .slak = 1 << 20, .pair = 256, .osmx = 30000 };
pub const Pair = struct { key: []const u8, val: []const u8 };
pub const Doc = struct { aren: std.mem.Allocator, tmpz: std.mem.Allocator, data: []const u8, objs: std.AutoHashMapUnmanaged(u32, []const u8) = .empty, budg: usize = CF.totz };
pub fn isWs(byt: u8) bool { return byt == 0 or byt == 9 or byt == 10 or byt == 12 or byt == 13 or byt == 32; }
pub fn isDel(byt: u8) bool { return mem.findScalar(u8, "()<>[]{}/%", byt) != null; }
pub fn skipWs(src: []const u8, from: usize) usize { var kix = from; while (kix < src.len) { if (isWs(src[kix])) { kix += 1; } else if (src[kix] == '%') { while (kix < src.len and src[kix] != '\n' and src[kix] != '\r') kix += 1; } else break; } return kix; }
fn strEnd(src: []const u8, from: usize) usize { var kix = from + 1; var depz: usize = 1; while (kix < src.len) : (kix += 1) { if (src[kix] == '\\') { kix += 1; } else if (src[kix] == '(') { depz += 1; } else if (src[kix] == ')') { depz -= 1; if (depz == 0) return kix + 1; } } return src.len; }
fn refEnd(src: []const u8, from: usize) ?usize { var kix = from; while (kix < src.len and std.ascii.isDigit(src[kix])) kix += 1; if (kix == from) return null; const aaa = kix; while (kix < src.len and isWs(src[kix])) kix += 1; if (kix == aaa) return null; const bbb = kix; while (kix < src.len and std.ascii.isDigit(src[kix])) kix += 1; if (kix == bbb) return null; const ccc = kix; while (kix < src.len and isWs(src[kix])) kix += 1; if (kix == ccc or kix >= src.len or src[kix] != 'R') return null; kix += 1; if (kix < src.len and !isWs(src[kix]) and !isDel(src[kix])) return null; return kix; }
pub fn valEnd(src: []const u8, from: usize) usize { if (from >= src.len) return src.len; const chr = src[from]; var kix = from; if (chr == '<' and from + 1 < src.len and src[from + 1] == '<') { var depz: usize = 0; while (kix + 1 < src.len) { if (src[kix] == '<' and src[kix + 1] == '<') { depz += 1; kix += 2; } else if (src[kix] == '>' and src[kix + 1] == '>') { depz -= 1; kix += 2; if (depz == 0) return kix; } else if (src[kix] == '(') { kix = strEnd(src, kix); } else kix += 1; } return src.len; } if (chr == '<') return (mem.findScalarPos(u8, src, from, '>') orelse src.len - 1) + 1; if (chr == '(') return strEnd(src, from); if (chr == '[') { var depz: usize = 0; while (kix < src.len) { if (src[kix] == '[') { depz += 1; kix += 1; } else if (src[kix] == ']') { depz -= 1; kix += 1; if (depz == 0) return kix; } else if (src[kix] == '(') { kix = strEnd(src, kix); } else kix += 1; } return src.len; } if (chr == '/') { kix += 1; while (kix < src.len and !isWs(src[kix]) and !isDel(src[kix])) kix += 1; return kix; } if (refEnd(src, from)) |rend| return rend; while (kix < src.len and !isWs(src[kix]) and !isDel(src[kix])) kix += 1; return @max(kix, from + 1); }
pub fn dictPairs(aren: std.mem.Allocator, body: []const u8) ![]Pair { const beg = mem.find(u8, body, "<<") orelse return &.{}; var list: std.ArrayList(Pair) = .empty; var kix = beg + 2; while (list.items.len < CF.pair) { kix = skipWs(body, kix); if (kix >= body.len or body[kix] != '/') break; const kst = kix + 1; var ken = kst; while (ken < body.len and !isWs(body[ken]) and !isDel(body[ken])) ken += 1; kix = skipWs(body, ken); if (kix >= body.len) break; const ven = valEnd(body, kix); try list.append(aren, .{ .key = body[kst..ken], .val = body[kix..ven] }); kix = ven; } return list.toOwnedSlice(aren); }
pub fn pairGet(ps: []const Pair, key: []const u8) ?[]const u8 { for (ps) |pair| if (mem.eql(u8, pair.key, key)) return pair.val; return null; }
pub fn refOf(val: []const u8) ?u32 { const trm = mem.trim(u8, val, " \t\r\n"); const rend = refEnd(trm, 0) orelse return null; if (rend != trm.len) return null; var kix: usize = 0; while (kix < trm.len and std.ascii.isDigit(trm[kix])) kix += 1; return std.fmt.parseInt(u32, trm[0..kix], 10) catch null; }
pub fn intOf(val: []const u8) ?i64 { return std.fmt.parseInt(i64, mem.trim(u8, val, " \t\r\n"), 10) catch null; }
fn encFlag(data: []const u8) bool { var kix: usize = 0; while (mem.findPos(u8, data, kix, "/Encrypt")) |hit| { kix = hit + 8; if (kix < data.len and (isWs(data[kix]) or data[kix] == '<' or std.ascii.isDigit(data[kix]))) return true; } return false; }
pub fn docOpen(aren: std.mem.Allocator, tmpz: std.mem.Allocator, data: []const u8) !Doc { if (mem.find(u8, data[0..@min(data.len, 1024)], "%PDF-") == null) return error.BadPdf; if (encFlag(data)) return error.Encrypted; var doc: Doc = .{ .aren = aren, .tmpz = tmpz, .data = data }; var kix: usize = 0; while (mem.findPos(u8, data, kix, "obj")) |hit| { kix = hit + 3; if (hit < 4 or (hit >= 3 and mem.eql(u8, data[hit - 3 .. hit], "end"))) continue; if (kix < data.len and std.ascii.isAlphabetic(data[kix])) continue; var jix = hit; while (jix > 0 and isWs(data[jix - 1])) jix -= 1; const gen = jix; while (jix > 0 and std.ascii.isDigit(data[jix - 1])) jix -= 1; if (jix == gen) continue; const gst = jix; while (jix > 0 and isWs(data[jix - 1])) jix -= 1; if (jix == gst) continue; const nen = jix; while (jix > 0 and std.ascii.isDigit(data[jix - 1])) jix -= 1; if (jix == nen) continue; const num = std.fmt.parseInt(u32, data[jix..nen], 10) catch continue; const endz = mem.findPos(u8, data, kix, "endobj") orelse data.len; if (doc.objs.count() >= CF.objz) return error.TooMany; try doc.objs.put(aren, num, data[kix..endz]); kix = endz; } if (doc.objs.count() == 0) return error.BadPdf; try objStms(&doc); return doc; }
pub fn streamOf(doc: *Doc, body: []const u8) ![]const u8 { const spos = mem.find(u8, body, "stream") orelse return error.NoStream; const ps = try dictPairs(doc.aren, body[0..spos]); var stt = spos + 6; if (stt < body.len and body[stt] == '\r') stt += 1; if (stt < body.len and body[stt] == '\n') stt += 1; var enn = mem.findLast(u8, body, "endstream") orelse body.len; if (enn < stt) enn = stt; var raw = body[stt..enn]; if (pairGet(ps, "Length")) |lenv| { if (intOf(lenv)) |lenz| { if (lenz >= 0 and stt + @as(usize, @intCast(lenz)) <= enn) raw = body[stt .. stt + @as(usize, @intCast(lenz))]; } else { while (raw.len > 0 and (raw[raw.len - 1] == '\n' or raw[raw.len - 1] == '\r')) raw = raw[0 .. raw.len - 1]; } } const filt = pairGet(ps, "Filter") orelse return raw; if (mem.find(u8, filt, "FlateDecode") == null and mem.find(u8, filt, "/Fl") == null) return error.Unsupported; if (mem.count(u8, filt, "/") > 1) return error.Unsupported; const limz = @min(@min(CF.infz, doc.budg), raw.len * CF.rati + CF.slak); var inpt = std.Io.Reader.fixed(raw); const win = try doc.tmpz.alloc(u8, flate.max_window_len); defer doc.tmpz.free(win); var deco = flate.Decompress.init(&inpt, .zlib, win); const outp = deco.reader.allocRemaining(doc.tmpz, .limited(limz)) catch |err| switch (err) { error.StreamTooLong => return error.Bomb, else => return error.BadStream }; defer doc.tmpz.free(outp); if (outp.len > doc.budg) return error.Bomb; doc.budg -= outp.len; return doc.aren.dupe(u8, outp); }
fn objStms(doc: *Doc) !void { var nums: std.ArrayList(u32) = .empty; defer nums.deinit(doc.tmpz); var iter = doc.objs.iterator(); while (iter.next()) |ent| { if (mem.find(u8, ent.value_ptr.*[0..@min(ent.value_ptr.len, 400)], "/ObjStm") != null) try nums.append(doc.tmpz, ent.key_ptr.*); } for (nums.items) |num| { const body = doc.objs.get(num).?; const spos = mem.find(u8, body, "stream") orelse continue; const ps = try dictPairs(doc.aren, body[0..spos]); const cnt = intOf(pairGet(ps, "N") orelse continue) orelse continue; const fst = intOf(pairGet(ps, "First") orelse continue) orelse continue; if (cnt < 1 or cnt > CF.osmx or fst < 0) continue; const dec = streamOf(doc, body) catch continue; var hdr = mem.tokenizeAny(u8, dec[0..@min(dec.len, @as(usize, @intCast(fst)))], " \t\r\n"); var ids: std.ArrayList(u32) = .empty; defer ids.deinit(doc.tmpz); var offs: std.ArrayList(usize) = .empty; defer offs.deinit(doc.tmpz); var kix: i64 = 0; while (kix < cnt) : (kix += 1) { const idt = hdr.next() orelse break; const oft = hdr.next() orelse break; const idv = std.fmt.parseInt(u32, idt, 10) catch break; const ofv = std.fmt.parseInt(usize, oft, 10) catch break; try ids.append(doc.tmpz, idv); try offs.append(doc.tmpz, ofv); } for (ids.items, 0..) |oid, idx| { const bst = @as(usize, @intCast(fst)) + offs.items[idx]; const ben = if (idx + 1 < offs.items.len) @as(usize, @intCast(fst)) + offs.items[idx + 1] else dec.len; if (bst > ben or ben > dec.len) continue; if (!doc.objs.contains(oid)) try doc.objs.put(doc.aren, oid, dec[bst..ben]); } } }
